function subtreeWithAllDeepest(root) {
  const dfs = (node) => {
    if (node === null) {
      return [0, null];
    }
    const [leftDepth, leftBest] = dfs(node.left);
    const [rightDepth, rightBest] = dfs(node.right);
    if (leftDepth > rightDepth) {
      return [leftDepth + 1, leftBest];
    }
    if (rightDepth > leftDepth) {
      return [rightDepth + 1, rightBest];
    }
    return [leftDepth + 1, node];
  };
  return dfs(root)[1];
}

