function subtreeWithAllDeepest(root) {
  // List every node with its depth, then keep the deepest node whose subtree holds all of the deepest nodes.
  const depth = new Map();
  const order = [];
  const walk = (node, d) => {
    if (node === null) return;
    depth.set(node, d);
    order.push(node);
    walk(node.left, d + 1);
    walk(node.right, d + 1);
  };
  walk(root, 0);
  const maxDepth = Math.max(...depth.values());
  const deepest = order.filter(node => depth.get(node) === maxDepth);
  const contains = (node, target) => node !== null && (node === target || contains(node.left, target) || contains(node.right, target));
  let best = root;
  for (const node of order) {
    if (depth.get(node) > depth.get(best) && deepest.every(target => contains(node, target))) best = node;
  }
  return best;
}

