function generate(rand, size) {
  const n = size === 'large' ? 400 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 12);
  // Distinct values drawn from 0..500.
  const pool = Array.from({ length: 501 }, (_, i) => i);
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  // Attach each new node to a free child slot; a high bias favours recent slots and grows long branches.
  const bias = rand();
  const nodes = [{ val: pool[0], left: null, right: null }];
  const slots = [[0, 'left'], [0, 'right']];
  for (let i = 1; i < n; i++) {
    const k = rand() < bias ? slots.length - 1 - Math.floor(rand() * Math.min(2, slots.length)) : Math.floor(rand() * slots.length);
    const [parent, side] = slots[k];
    slots[k] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    nodes.push({ val: pool[i], left: null, right: null });
    slots.push([i, 'left'], [i, 'right']);
  }
  const out = [];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    const node = nodes[queue[q]];
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return [out];
}
